import unittest

class TestSecurePasswordGenerator(unittest.TestCase):
    def test_password_length(self):
        generator = SecurePasswordGenerator()
        password = generator.generate_password(12)
        self.assertEqual(len(password), 12)

    def test_password_characters(self):
        generator = SecurePasswordGenerator()
        password = generator.generate_password(12)
        for char in password:
            self.assertIn(char, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-=[]{}|;:,.<>?')

    def test_unique_characters(self):
        generator = SecurePasswordGenerator()
        password = generator.generate_password(12)
        self.assertLen(set(password), 12)

if __name__ == '__main__':
    unittest.main()

